def check_alice_wins(binary_string):
    def evaluate_expression(expression):
        stack = []
        for char in expression:
            if char == '1':
                stack.append(char)
            elif char == '0':
                if len(stack) > 1:
                    stack.pop()
                else:
                    return False
            elif char == '&':
                if len(stack) < 2:
                    return False
                stack[-2] += stack.pop()
            elif char == '|':
                if len(stack) < 2:
                    return False
                stack[-2] |= stack.pop()
        return True

    alice_turn = True
    current_expression = ''

    for i in range(len(binary_string)):
        current_expression += binary_string[i]

        if i % 2 == 0 and alice_turn:
            if evaluate_expression(current_expression):
                return 'YES'
            current_expression = ''
            alice_turn = False
        elif i % 2 != 0 and not alice_turn:
            if evaluate_expression(current_expression):
                return 'NO'
            current_expression = ''
            alice_turn = True

    # Check the last expression
    if evaluate_expression(current_expression):
        return 'YES'
    return 'NO'

