def find_winning_index(n, k, a):
    # Check if there exists at least one pair (i, j) such that |a[i] - a[j]| % k != 0
    for i in range(n):
        for j in range(i + 1, n):
            if abs(a[i] - a[j]) % k != 0:
                return True
    return False

