def adjacent_digit_sums(x, y):
    def digit_sum(num):
        return sum(int(digit) for digit in str(num))

    for n in range(x, y + 1):
        if digit_sum(n) == x and digit_sum(n + 1) == y:
            return "YES"
    return "NO"

