def find_day(n, a, b, c):
    total_distance = 0
    day = 1

    while total_distance < n:
        if day % 4 == 1 or day % 4 == 2:
            total_distance += a
        elif day % 4 == 3 or day % 4 == 0:
            total_distance += b
        day += 1

    return day

