def f(s):
    count = [0] * 26
    for c in s:
        count[ord(c) - ord('a')] += 1
    return sum(count) % 2 == 0

def find_valid_string(s):
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            if f(s[i:j]):
                return s[i:j]
    return "-1"

